def get(path, timeout=10):
    try:
        with urllib.request.urlopen(BASE + path, timeout=timeout) as r:
            return json.loads(r.read())
    except Exception as e:
        return {"_error": str(e)}

def brief(d):
    if "_error" in d:
        return "ERR " + d["_error"]
    parts = [d.get("phase")]
    parts.append("cd=" + str(d.get("challenge_deadline")))
    parts.append("cmd=" + str(d.get("commit_deadline")))
    parts.append("rd=" + str(d.get("reveal_deadline")))
    parts.append("dep=" + str(d.get("total_deposited_wei")))
    parts.append("C=" + repr(d.get("content")))
    parts.append("E=" + repr(d.get("evidence")))
    js = [(j["actor_id"], j["commitment"] is not None, j["revealed"], j["verdict"]) for j in d.get("jurors", [])]
    parts.append("J=" + str(js))
    parts.append("v=%s/%s" % (d.get("creator_votes"), d.get("challenger_votes")))
    return " | ".join(parts)

if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    gap = float(sys.argv[2]) if len(sys.argv) > 2 else 10
    for i in range(n):
        print(time.strftime("%H:%M:%S"), brief(get("/v1/episodes/" + EP)), flush=True)
        if i < n - 1:
            time.sleep(gap)

import json, sys, time, urllib.request, urllib.error, os

BASE = "http://game:8080"
EP = "run-5f1ef60523ba-0001"
STATE = "/workspace/actions.jsonl"

VERDICT = os.environ.get("VERDICT", "CREATOR_SUPPORTED")
ASSESSMENT = os.environ.get("ASSESSMENT", "")

def get(path, timeout=15):
    try:
        with urllib.request.urlopen(BASE + path, timeout=timeout) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        return {"_http_error": e.code, "_body": e.read().decode(errors="replace")}
    except Exception as e:
        return {"_error": str(e)}

def post(path, key, body, timeout=30):
    data = json.dumps(body).encode()
    req = urllib.request.Request(BASE + path, data=data, method="POST",
                                 headers={"Content-Type": "application/json",
                                          "Idempotency-Key": key})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors="replace")
    except Exception as e:
        return None, str(e)

def log(rec):
    rec["ts"] = time.time()
    with open(STATE, "a") as f:
        f.write(json.dumps(rec) + "\n")
    print("LOGGED:", json.dumps(rec)[:400], flush=True)

def do_commit(key, verdict, assessment):
    body = {"verdict": verdict, "assessment": assessment}
    log({"kind": "commit-request", "key": key, "body": body})
    code, resp = post("/v1/episodes/%s/commitments" % EP, key, body)
    log({"kind": "commit-response", "key": key, "code": code, "resp": resp})
    return code, resp

def do_reveal(key):
    log({"kind": "reveal-request", "key": key})
    code, resp = post("/v1/episodes/%s/reveals" % EP, key, {})
    log({"kind": "reveal-response", "key": key, "code": code, "resp": resp})
    return code, resp

def op_status(opid):
    return get("/v1/operations/" + opid)

if __name__ == "__main__":
    action = sys.argv[1]
    key = sys.argv[2]
    if action == "commit":
        print(do_commit(key, VERDICT, ASSESSMENT))
    elif action == "reveal":
        print(do_reveal(key))
    elif action == "status":
        d = get("/v1/episodes/" + EP)
        print(json.dumps({k: d.get(k) for k in ("phase", "challenge_deadline", "commit_deadline", "reveal_deadline", "total_deposited_wei", "creator_votes", "challenger_votes")}, indent=1))
        print("jurors:", json.dumps(d.get("jurors"), indent=1))
        print("evidence:", repr(d.get("evidence"))[:1500])
        print("content:", repr(d.get("content"))[:1500])
    elif action == "op":
        print(json.dumps(op_status(key), indent=1))

